package com.retro.launcher;
import android.graphics.*;
import java.util.*;
final class ChromePack {
 final MainActivity a; final Map<String,Bitmap> cache=new HashMap<>(); final Paint paint=new Paint(3);
 ChromePack(MainActivity activity){a=activity;}
 Bitmap get(String name){if(cache.containsKey(name))return cache.get(name);Bitmap b=null;try(java.io.InputStream in=a.getAssets().open("chrome/"+name)){BitmapFactory.Options o=new BitmapFactory.Options();if(name.contains("wallpaper"))o.inSampleSize=2;b=BitmapFactory.decodeStream(in,null,o);}catch(Exception ignored){}cache.put(name,b);return b;}
 boolean draw(Canvas c,String name,float x,float y,float w,float h){Bitmap b=get(name);if(b==null)return false;paint.setColor(Color.WHITE);paint.setShader(null);c.drawBitmap(b,null,new RectF(x,y,x+w,y+h),paint);return true;}
 void bar(Canvas c,String name,float x,float y,float w,float h){Bitmap b=get("ui/"+name+".png");if(b==null)return;int cap=Math.min(b.getHeight()/2,b.getWidth()/3);float edge=Math.min(h/2,w/3);paint.setColor(Color.WHITE);c.drawBitmap(b,new Rect(0,0,cap,b.getHeight()),new RectF(x,y,x+edge,y+h),paint);c.drawBitmap(b,new Rect(cap,0,b.getWidth()-cap,b.getHeight()),new RectF(x+edge,y,x+w-edge,y+h),paint);c.drawBitmap(b,new Rect(b.getWidth()-cap,0,b.getWidth(),b.getHeight()),new RectF(x+w-edge,y,x+w,y+h),paint);}
 void wallpaper(Canvas c,float w,float h){Bitmap b=get("wallpapers/night_orbit_1080x1920.jpg");if(b==null)return;float scale=Math.max(w/b.getWidth(),h/b.getHeight());float bw=b.getWidth()*scale,bh=b.getHeight()*scale;paint.setColor(Color.WHITE);c.drawBitmap(b,null,new RectF((w-bw)/2,(h-bh)/2,(w+bw)/2,(h+bh)/2),paint);paint.setColor(0x66000819);c.drawRect(0,0,w,h,paint);}
 String icon(MainActivity.App app){String override=a.prefs.getString("icon:"+app.id,"");if(!override.isEmpty())return override.equals("original")?null:override;String s=app.id.toLowerCase(Locale.ROOT),n=app.label.toLowerCase(Locale.ROOT);String extra=MillenniumIcons.forPackage(s);if(extra!=null)return extra;if(s.contains("dialer")||n.equals("phone"))return "phone";if(s.contains("cmail")||s.contains("messaging")||n.equals("messages"))return "messages";if(s.contains("contacts"))return "contacts";if(s.contains("camera"))return "camera";if(s.contains("music"))return "music";if(s.contains("gallery")||s.contains("photos"))return "gallery";if(s.contains("browser")||s.contains("chrome"))return "browser";if(s.contains("calendar"))return "calendar";if(s.contains("settings"))return "settings";return null;}
 boolean icon(Canvas c,MainActivity.App app,float x,float y,float r){String name=icon(app);if(name==null)return false;Bitmap b=get("icons/transparent/"+name+".png");if(b==null)return false;c.save();Path clip=new Path();clip.addCircle(x,y,r,Path.Direction.CW);c.clipPath(clip);paint.setColor(Color.WHITE);c.drawBitmap(b,null,new RectF(x-r,y-r,x+r,y+r),paint);c.restore();return true;}
}
